-- Any error, including a lock wait over 5 s, rolls everything back; nothing is half-applied.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

-- A02/P01: permintaan koreksi pembelian yang tersimpan dan terikat dokumen asal.
--
-- Aturan yang dipakai (sudah berlaku di aplikasi, tidak ditambah):
-- - Koreksi resmi PO/faktur hanya oleh Super Admin (OWNER aktif) lewat kontrol
--   koreksi yang sudah ada. Peran lain melapor/meminta koreksi, bukan mengubah.
-- - Pemohon harus boleh membuka modul Pembelian dan cabang dokumennya.
--
-- Request hanyalah catatan pekerjaan untuk Super Admin. Membuat atau memproses
-- request TIDAK mengubah PO, faktur, pembayaran, stok, atau jurnal apa pun.
-- Siklus: pending -> selesai (sudah diproses OWNER aktif, catatan tindak lanjut wajib).
-- Tidak ada status tolak/batal; itu menunggu keputusan bisnis terpisah.

create table public.purchase_correction_requests (
  id uuid primary key default gen_random_uuid(),
  source_kind text not null check (source_kind in ('purchase_order', 'purchase_invoice')),
  po_id uuid references public.purchase_orders(id),
  invoice_id uuid references public.purchase_invoices(id),
  -- Cabang dokumen asal saat request dibuat; dipakai untuk membatasi pembaca.
  branch_id uuid references public.branches(id),
  -- Nomor dokumen saat request dibuat, agar antrean tetap terbaca.
  source_label text not null check (length(source_label) between 1 and 120),
  detail text not null check (length(btrim(detail)) between 10 and 2000),
  requested_by uuid not null references public.profiles(id),
  request_key text not null check (request_key ~ '^[A-Za-z0-9._:-]{8,120}$'),
  status text not null default 'pending' check (status in ('pending', 'selesai')),
  processed_by uuid references public.profiles(id),
  processed_at timestamptz,
  resolution text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (requested_by, request_key),
  check ((source_kind = 'purchase_order') = (po_id is not null and invoice_id is null)
     and (source_kind = 'purchase_invoice') = (invoice_id is not null and po_id is null)),
  check ((status = 'selesai') = (processed_by is not null and processed_at is not null and resolution is not null)),
  check (resolution is null or length(btrim(resolution)) between 3 and 1000)
);
create index purchase_correction_requests_queue on public.purchase_correction_requests (status, created_at desc, id);
create index purchase_correction_requests_po on public.purchase_correction_requests (po_id, created_at desc) where po_id is not null;
create index purchase_correction_requests_invoice on public.purchase_correction_requests (invoice_id, created_at desc) where invoice_id is not null;

-- Mirrors src/lib/akses.ts modulDiizinkan() for module `pembelian`: OWNER always;
-- stored Akses Grup rows win; otherwise ADMIN/DOCTOR keep the full default while
-- FINANCE/STAFF defaults do not include Pembelian.
create function public.purchase_module_access() returns boolean
language sql stable security definer set search_path='' as $$
  select exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_active is true and (
    p.role='OWNER'
    or exists(select 1 from public.role_modules m where m.role=p.role and m.module_id='pembelian')
    or (p.role in ('ADMIN','DOCTOR') and not exists(select 1 from public.role_modules m where m.role=p.role))
  ));
$$;
revoke all on function public.purchase_module_access() from public,anon,service_role;
grant execute on function public.purchase_module_access() to authenticated;

create function public.purchase_correction_request_visible(p_requested_by uuid, p_branch uuid) returns boolean
language sql stable security definer set search_path='' as $$
  select auth.uid() is not null and public.purchase_module_access()
    and (p_branch is null or public.user_can_access_branch(p_branch))
    and (p_requested_by = auth.uid()
      or exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='OWNER' and p.is_active));
$$;
revoke all on function public.purchase_correction_request_visible(uuid,uuid) from public,anon,service_role;
grant execute on function public.purchase_correction_request_visible(uuid,uuid) to authenticated;

alter table public.purchase_correction_requests enable row level security;
revoke all on public.purchase_correction_requests from public,anon,authenticated,service_role;
grant select on public.purchase_correction_requests to authenticated;
-- Pemohon melihat request miliknya; Super Admin melihat antrean cabang yang boleh ia buka.
create policy purchase_correction_requests_read on public.purchase_correction_requests
  for select to authenticated using (public.purchase_correction_request_visible(requested_by, branch_id));

create function public.create_purchase_correction_request(
  p_source_kind text, p_source_id uuid, p_request_key text, p_detail text
) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  actor_role text; branch uuid; label text; v_po uuid; v_invoice uuid; v_detail text := btrim(coalesce(p_detail, ''));
  prior public.purchase_correction_requests%rowtype; r public.purchase_correction_requests%rowtype;
begin
  select p.role::text into actor_role from public.profiles p where p.id=auth.uid() and p.is_active;
  if auth.uid() is null or actor_role is null or not public.purchase_module_access() then
    raise exception 'Akses Pembelian diperlukan untuk meminta koreksi' using errcode='42501';
  end if;
  if actor_role = 'OWNER' then
    raise exception 'Super Admin memakai kontrol koreksi pada dokumen; permintaan tidak diperlukan' using errcode='42501';
  end if;
  if p_request_key is null or p_request_key !~ '^[A-Za-z0-9._:-]{8,120}$' then
    raise exception 'Identitas permintaan tidak valid; muat ulang halaman' using errcode='22023';
  end if;
  if length(v_detail) not between 10 and 2000 then
    raise exception 'Tulis rincian koreksi 10 sampai 2.000 karakter' using errcode='22023';
  end if;

  if p_source_kind = 'purchase_order' then
    select o.id, o.branch_id, coalesce(o.no_po, 'PO tanpa nomor') into v_po, branch, label
      from public.purchase_orders o where o.id = p_source_id;
  elsif p_source_kind = 'purchase_invoice' then
    select i.id, coalesce(i.branch_id, o.branch_id), i.no_faktur into v_invoice, branch, label
      from public.purchase_invoices i left join public.purchase_orders o on o.id = i.po_id where i.id = p_source_id;
  else
    raise exception 'Jenis dokumen asal tidak dikenal' using errcode='22023';
  end if;
  -- Sama dengan RLS baca dokumen asal: PO tanpa cabang terbuka; faktur selalu lewat
  -- user_can_access_branch (cabang faktur, atau cabang PO-nya), termasuk bila kosong.
  if (v_po is null and v_invoice is null)
     or (v_po is not null and branch is not null and not public.user_can_access_branch(branch))
     or (v_invoice is not null and not public.user_can_access_branch(branch)) then
    raise exception 'Dokumen asal tidak ditemukan atau tidak dapat diakses' using errcode='42501';
  end if;

  -- Klik ganda/kirim ulang form yang sama menghasilkan satu request.
  perform pg_advisory_xact_lock(hashtext('vetos:purchase-correction:' || auth.uid()::text || ':' || p_request_key)::bigint);
  select * into prior from public.purchase_correction_requests where requested_by=auth.uid() and request_key=p_request_key;
  if found then
    if prior.source_kind is distinct from p_source_kind or prior.po_id is distinct from v_po
       or prior.invoice_id is distinct from v_invoice or prior.detail is distinct from v_detail then
      raise exception 'Identitas permintaan sudah dipakai dengan isi berbeda; muat ulang halaman' using errcode='23505';
    end if;
    r := prior;
  else
    insert into public.purchase_correction_requests(source_kind, po_id, invoice_id, branch_id, source_label, detail, requested_by, request_key)
      values (p_source_kind, v_po, v_invoice, branch, left(label, 120), v_detail, auth.uid(), p_request_key)
      returning * into r;
  end if;
  return jsonb_build_object('id', r.id, 'status', r.status, 'source_kind', r.source_kind,
    'source_id', coalesce(r.po_id, r.invoice_id), 'created_at', r.created_at);
end$$;
revoke all on function public.create_purchase_correction_request(text,uuid,text,text) from public,anon,service_role;
grant execute on function public.create_purchase_correction_request(text,uuid,text,text) to authenticated;

create function public.process_purchase_correction_request(p_id uuid, p_resolution text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.purchase_correction_requests%rowtype; v_resolution text := btrim(coalesce(p_resolution, ''));
begin
  if auth.uid() is null or not exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='OWNER' and p.is_active) then
    raise exception 'Hanya Super Admin aktif yang dapat memproses permintaan koreksi' using errcode='42501';
  end if;
  if length(v_resolution) not between 3 and 1000 then
    raise exception 'Tulis tindak lanjut 3 sampai 1.000 karakter' using errcode='22023';
  end if;
  select * into r from public.purchase_correction_requests where id=p_id for update;
  if not found or (r.branch_id is not null and not public.user_can_access_branch(r.branch_id)) then
    raise exception 'Permintaan koreksi tidak ditemukan atau tidak dapat diakses' using errcode='42501';
  end if;
  if r.status = 'selesai' then
    if r.processed_by = auth.uid() and r.resolution = v_resolution then
      return jsonb_build_object('id', r.id, 'status', r.status, 'processed_at', r.processed_at);
    end if;
    raise exception 'Permintaan koreksi sudah diproses' using errcode='55000';
  end if;
  -- Hanya status request yang berubah. Dokumen asal dan transaksi turunannya tidak disentuh.
  update public.purchase_correction_requests
     set status='selesai', processed_by=auth.uid(), processed_at=now(), resolution=v_resolution, updated_at=now()
   where id=p_id returning * into r;
  return jsonb_build_object('id', r.id, 'status', r.status, 'processed_at', r.processed_at);
end$$;
revoke all on function public.process_purchase_correction_request(uuid,text) from public,anon,service_role;
grant execute on function public.process_purchase_correction_request(uuid,text) to authenticated;

